#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t; cin >> t;
    while(t--) {
        int n; cin >> n;
        vector<int>a(n);
        for(int i=0;i<n;i++) cin >> a[i];
        vector<int>ans;
        for(int i=1;i<n;i++) {
            ans.push_back(abs(a[i]-a[i-1]));
        }
        ans.push_back(abs(a[0]-a[n-1]));
        sort(ans.begin(),ans.end(),greater<int>());
        if(ans.size()==1) {
            cout << ans[0] << endl;
        }else cout << ans[1] << endl;
        
    }
}
